parameters.jsCode:
// ==========================================================================
// ENGENHARIA DEFENSIVA: Validação de Schema, Sanitização e Normalização NLP
// ==========================================================================
const rawInput = $input.first().json.body || $input.first().json || {};

const rawFrom = rawInput.from;
const rawMensagem = rawInput.mensagem;

// 1. Validação de presença dos campos obrigatórios
if (!rawFrom || !rawMensagem || typeof rawMensagem !== 'string' || rawMensagem.trim().length === 0) {
  return [{
    json: {
      isValid: false,
      errorCode: 'INVALID_PAYLOAD',
      errorMessage: "Os campos 'from' (telefone/ID) e 'mensagem' (texto não vazio) são obrigatórios.",
      received: rawInput
    }
  }];
}

// 2. Sanitização de telefone (apenas números)
const usuario = String(rawFrom).replace(/\D/g, '') || String(rawFrom).trim();

// 3. Pipeline de Normalização NLP (remoção de acentos/diacríticos, trim, lowercase)
const textoNormalizado = rawMensagem
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

return [{
  json: {
    isValid: true,
    usuario,
    texto: textoNormalizado,
    mensagemOriginal: rawMensagem.trim(),
    receivedAt: new Date().toISOString()
  }
}];

// ==========================================================================
// CLASSIFICAÇÃO SEMÂNTICA DE INTENÇÃO (Semantic Intent Engine)
// ==========================================================================
const { texto, usuario, mensagemOriginal, receivedAt } = $input.first().json;

// Dicionários de termos-chave para categorização de intenção
const intencoes = {
  SUPORTE_URGENTE: ['ajuda', 'ajuda-me', 'socorro', 'urgente', 'problema', 'defeito', 'quebrou', 'falha', 'erro', 'travou'],
  COMERCIAL_VENDAS: ['comprar', 'preco', 'valor', 'orcamento', 'catalogo', 'produto', 'quanto custa', 'promocao'],
  CANCELAMENTO: ['cancelar', 'estorno', 'reembolso', 'devolucao', 'desistir']
};

let intencaoIdentificada = 'DUVIDA_GERAL';
let confianca = 0.70;
let termosCasados = [];

for (const [intencao, termos] of Object.entries(intencoes)) {
  const matches = termos.filter(t => texto.includes(t));
  if (matches.length > 0) {
    intencaoIdentificada = intencao;
    termosCasados = matches;
    confianca = Math.min(0.98, 0.75 + (matches.length * 0.1));
    break;
  }
}

return [{
  json: {
    usuario,
    mensagemOriginal,
    intencao: intencaoIdentificada,
    confianca,
    termosCasados,
    receivedAt,
    processedAt: new Date().toISOString()
  }
}];

